package com.chdjalil.jalilgym.core.database.seed

import kotlinx.serialization.Serializable

/** Shape of `assets/seed/recipes.json` (generated by tools/seed/recipes.py). Bump [version] on changes. */
@Serializable
data class RecipeSeedFile(
    val version: Int,
    val recipes: List<SeedRecipe>,
)

@Serializable
data class SeedRecipe(
    val id: String,
    val name: String,
    val servings: Int,
    /** MealType names. */
    val meals: List<String>,
    val ingredients: List<SeedIngredient>,
    val steps: List<String> = emptyList(),
)

/** [food] is a seed food id. */
@Serializable
data class SeedIngredient(val food: String, val grams: Double)
